// Load due scheduled actions + proactive reminder check + open loop check
const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const CHAT_ID = '{{TELEGRAM_CHAT_ID}}';
const http = this.helpers.httpRequest;

async function pgrest(path) {
  const res = await http({
    method: 'GET',
    url: `${SUPABASE_URL}${path}`,
    headers: { 'apikey': SUPABASE_KEY, 'Content-Type': 'application/json' },
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });
  return typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
}

const userId = `telegram:${CHAT_ID}`;
const now = new Date();
const nowISO = now.toISOString();

// Load all context in parallel
const [dueActions, tasks, profiles, heartbeatCfg, mcpServers, openLoopCfg] = await Promise.all([
  pgrest(`/rest/v1/scheduled_actions?enabled=eq.true&next_run=lte.${nowISO}&order=next_run.asc`),
  pgrest(`/rest/v1/tasks?user_id=eq.${encodeURIComponent(userId)}&status=in.(pending,in_progress)&order=due_date.asc.nullslast,priority.desc`),
  pgrest(`/rest/v1/user_profiles?user_id=eq.${encodeURIComponent(userId)}&select=display_name,timezone,preferences`),
  pgrest('/rest/v1/heartbeat_config?check_name=eq.heartbeat&select=config,last_run,enabled'),
  pgrest('/rest/v1/mcp_registry?active=eq.true&select=server_name,mcp_url,description,tools'),
  pgrest('/rest/v1/heartbeat_config?check_name=eq.open_loop_check&select=config,last_run,enabled')
]);

const profile = (Array.isArray(profiles) && profiles.length > 0) ? profiles[0] : {};
const prefs = profile.preferences || {};
const tz = profile.timezone || 'Europe/Berlin';
const lang = prefs.language || 'German';

// Build MCP skills text for background checker
let mcpSkillsText = '';
if (Array.isArray(mcpServers) && mcpServers.length > 0) {
  mcpSkillsText = mcpServers.map(s => {
    const tools = Array.isArray(s.tools) ? s.tools.join(', ') : '';
    return `- ${s.server_name}: ${s.mcp_url} (tools: ${tools}) — ${s.description || ''}`;
  }).join('\n');
}

// Build result items from due scheduled actions
const items = [];

if (Array.isArray(dueActions)) {
  for (const action of dueActions) {
    items.push({
      json: {
        type: 'scheduled_action',
        actionId: action.id,
        message: action.instruction,
        chat_id: action.chat_id,
        user_id: action.user_id,
        source: 'scheduled_action',
        schedule: action.schedule,
        timezone: action.timezone || tz,
        run_count: action.run_count || 0,
        max_runs: action.max_runs,
        name: action.name,
        notify_mode: action.notify_mode || 'always',
        last_run: action.last_run || null,
        mcp_skills: mcpSkillsText,
        language: lang
      }
    });
  }
}

// Proactive reminder check (existing logic — kept as synthetic item)
const hbEnabled = (Array.isArray(heartbeatCfg) && heartbeatCfg.length > 0) ? heartbeatCfg[0].enabled : false;
const hbLastRun = (Array.isArray(heartbeatCfg) && heartbeatCfg.length > 0 && heartbeatCfg[0].last_run) ? new Date(heartbeatCfg[0].last_run) : null;
const hbMinInterval = (Array.isArray(heartbeatCfg) && heartbeatCfg.length > 0 && heartbeatCfg[0].config) ? (heartbeatCfg[0].config.min_interval_hours || 2) : 2;

if (hbEnabled) {
  const hoursSinceLastRun = hbLastRun ? (now.getTime() - hbLastRun.getTime()) / (1000 * 60 * 60) : 999;
  if (hoursSinceLastRun >= hbMinInterval) {
    const taskList = Array.isArray(tasks) ? tasks : [];
    const overdue = taskList.filter(t => t.due_date && new Date(t.due_date) < now);
    const urgentCutoff = new Date(now.getTime() + 24 * 60 * 60 * 1000);
    const urgent = taskList.filter(t => t.priority === 'urgent' && (!t.due_date || new Date(t.due_date) <= urgentCutoff));

    if (overdue.length > 0 || urgent.length > 0) {
      let instruction = `You are proactively checking in with the user. Respond in ${lang}. Send a brief, helpful reminder (1-3 sentences) about these items:\n`;
      if (overdue.length > 0) {
        instruction += `\nOverdue tasks:\n${overdue.map(t => `- ${t.title} (due: ${t.due_date}, priority: ${t.priority})`).join('\n')}`;
      }
      if (urgent.length > 0) {
        instruction += `\nUrgent tasks:\n${urgent.map(t => `- ${t.title}`).join('\n')}`;
      }
      instruction += `\n\nBe helpful, not annoying. If nothing seems worth messaging about, just skip this.`;

      items.push({
        json: {
          type: 'proactive_reminder',
          heartbeat_check_name: 'heartbeat',
          actionId: null,
          message: instruction,
          chat_id: CHAT_ID,
          user_id: userId,
          source: 'scheduled_action',
          notify_mode: 'always'
        }
      });
    }
  }
}

// Offene Vorhaben (Runde 10, 19.10.2026): die Nachfrage geht an die Person,
// der das Vorhaben gehoert (memory_long.owner_user_id), in ihren eigenen Chat.
// Bis dahin gingen alle offenen Punkte gesammelt an die Telegram-Nummer des
// Betreibers: Michaels SL-Card-Broschuere kam am 16., 17. und 18.10.2026 bei
// Freddy an, Michael selbst hoerte nichts. Damit Rupert nicht draengelt:
//   - je Vorhaben genau EINE Nachfrage (metadata.nachgefragt_am, vor dem Absenden gesetzt)
//   - je Person hoechstens eine Nachricht je Lauf, mit bis zu drei Punkten,
//     hoechstens MAX_PERSONEN Personen je Lauf (die Bruecke nimmt 30 Nachrichten
//     je 10 Minuten fuer alle Wege zusammen); config.max_personen, Vorgabe 8
//   - nur werktags von 8 bis 17 Uhr Wiener Zeit, nicht an oesterreichischen
//     Feiertagen; config.zeitfenster.feiertage nimmt weitere Tage als
//     'YYYY-MM-DD' oder 'DD.MM.YYYY' (zum Beispiel 24.12., 31.12., 24.09.)
//   - Vorhaben ohne Besitzer bleiben liegen; ohne erreichbaren persoenlichen Chat
//     werden sie vermerkt (nachfrage_unzustellbar_am) und nach 14 Tagen erneut versucht
// Runde 10b (Review 19.10.2026): erledigte, schon gefragte, besitzerlose und eben
// unzustellbare Eintraege filtert die Datenbank, sonst fuellten sie das Fenster
// von 50 Zeilen, und neue Vorhaben kaemen nie dran. Alle Abfragen laufen mit dem
// Dienstschluessel (Bearer): user_identity_map ist fuer die anon-Rolle gesperrt
// (Migration 013), ohne Bearer kam die Zuordnung nie an. Erst wird die Kennung
// aufgeloest (entra: -> web: ueber user_identity_map, wie im Teams-Adapter), dann
// je Person gebuendelt: eine Person mit Vorhaben unter beiden Kennungen bekommt
// EINE Nachricht. Die Nachfragen stehen vorn in der Liste: der Agent laeuft ohne
// Warten, scheitert danach eine andere Aktion, sind sie trotzdem unterwegs und
// last_run ist gesetzt.
// Der Agent laeuft als diese Person (Profil, Verlauf, Gedaechtnis), die Antwort
// bringt die Zustellung in den Teams-Chat oder in den Web-Verlauf.
const olCfg = (Array.isArray(openLoopCfg) && openLoopCfg.length > 0) ? openLoopCfg[0] : null;
const olEnabled = olCfg ? olCfg.enabled : false;
const olLastRun = (olCfg && olCfg.last_run) ? new Date(olCfg.last_run) : null;
const olConf = (olCfg && olCfg.config) || {};
const olMinInterval = olConf.min_interval_hours || 24;
const olMinAgeDays = olConf.min_age_days || 3;
const olFenster = Object.assign({ zeitzone: 'Europe/Vienna', von: 8, bis: 17, werktage: true, feiertage: [] }, olConf.zeitfenster || {});
const MAX_PERSONEN = (typeof olConf.max_personen === 'number' && olConf.max_personen > 0) ? olConf.max_personen : 8;
const UNZUSTELLBAR_TAGE = 14;

// Gesetzliche Feiertage in Oesterreich: feste Tage plus die von Ostern abhaengigen.
function osterSonntag(j) {
  const a = j % 19, b = Math.floor(j / 100), c = j % 100, d = Math.floor(b / 4), e = b % 4;
  const f = Math.floor((b + 8) / 25), g = Math.floor((b - f + 1) / 3), h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4), k = c % 4, l = (32 + 2 * e + 2 * i - h - k) % 7, m = Math.floor((a + 11 * h + 22 * l) / 451);
  return new Date(Date.UTC(j, Math.floor((h + l - 7 * m + 114) / 31) - 1, ((h + l - 7 * m + 114) % 31) + 1));
}
function feiertagAT(j, mo, t) {
  const tag = String(mo).padStart(2, '0') + '-' + String(t).padStart(2, '0');
  if (['01-01', '01-06', '05-01', '08-15', '10-26', '11-01', '12-08', '12-25', '12-26'].includes(tag)) return true;
  const o = osterSonntag(j).getTime();
  const heute = Date.UTC(j, mo - 1, t);
  return [1, 39, 50, 60].some(n => o + n * 864e5 === heute);   // Ostermontag, Himmelfahrt, Pfingstmontag, Fronleichnam
}
// Weitere freie Tage aus der config, als 'YYYY-MM-DD' oder 'DD.MM.YYYY'
function alsIsoTag(s) {
  const t = String(s || '').trim();
  let m = t.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return m[1] + '-' + m[2] + '-' + m[3];
  m = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  if (m) return m[3] + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0');
  return null;
}
const olFreieTage = (Array.isArray(olFenster.feiertage) ? olFenster.feiertage : []).map(alsIsoTag).filter(Boolean);

function imZeitfenster(d) {
  try {
    const lokal = new Date(d.toLocaleString('en-US', { timeZone: olFenster.zeitzone }));
    const tag = lokal.getDay();
    const stunde = lokal.getHours();
    if (olFenster.werktage && (tag === 0 || tag === 6)) return false;
    const j = lokal.getFullYear(), mo = lokal.getMonth() + 1, t = lokal.getDate();
    const iso = j + '-' + String(mo).padStart(2, '0') + '-' + String(t).padStart(2, '0');
    if (olFenster.werktage && feiertagAT(j, mo, t)) return false;
    if (olFreieTage.includes(iso)) return false;
    return stunde >= olFenster.von && stunde < olFenster.bis;
  } catch (e) { return false; }
}

// Lesen mit dem Dienstschluessel. Liefert die Liste oder null, wenn die Antwort
// keine Liste ist (Fehler, gesperrt, Datenbank weg).
async function holen(path) {
  const res = await http({
    method: 'GET',
    url: `${SUPABASE_URL}${path}`,
    headers: { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${SUPABASE_KEY}`, 'Content-Type': 'application/json' },
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });
  let body = res ? res.body : null;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
  return Array.isArray(body) ? body : null;
}

async function vorhabenVermerken(ol, feld) {
  await http({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/memory_long?id=eq.${ol.id}`,
    headers: { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${SUPABASE_KEY}`, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
    body: { metadata: Object.assign({}, ol.metadata || {}, { [feld]: nowISO }) }
  });
}

// Wohin die Nachfrage geht. Telegram ueber die Nummer. Sonst zuerst die Kennung
// aufloesen, dann der persoenliche Teams-Chat der Person, wenn es einen gibt
// (dort liest sie, und der Verlauf ist derselbe wie im Web, Runde 5), sonst ihre
// Web-Sitzung. Ohne persoenlichen Teams-Chat und ohne Web-Sitzung (nur Kanaele,
// fremdes Format) ist sie unzustellbar: die Antwort laege ausserhalb ihres
// Verlaufs. Ist eine Abfrage nicht lesbar, ist das ein Fehler fuer diesen Lauf,
// keine Unzustellbarkeit.
async function zielVon(owner) {
  if (/^telegram:\d+$/.test(owner)) return { ziel: { user_id: owner, chat_id: owner.slice(9) } };
  if (/^\d+$/.test(owner)) return { ziel: { user_id: 'telegram:' + owner, chat_id: owner } };
  let wer = owner;
  if (/^entra:/.test(owner)) {
    const m = await holen(`/rest/v1/user_identity_map?entra_key=eq.${encodeURIComponent(owner)}&select=legacy_key&order=linked_at.desc&limit=1`);
    if (!m) return { fehler: true };
    if (m[0] && m[0].legacy_key) wer = m[0].legacy_key;
    // Wurde Microsoft aus Telegram verbunden, ist der juengste Schluessel
    // telegram:<nummer>. Dann geht die Nachfrage nach Telegram: der Agent behandelt
    // jede telegram:-Kennung als Telegram, ein Teams-Chat als Ziel liefe dort ins
    // Leere (dritte Gegenlese; bei SLT nur das Betreiberkonto, Stand 19.10. keins).
    if (/^telegram:\d+$/.test(wer)) return { ziel: { user_id: wer, chat_id: wer.slice(9) } };
  }
  const s = await holen(`/rest/v1/conversations?user_id=eq.${encodeURIComponent(wer)}&session_id=like.${encodeURIComponent('teams:a:*')}&select=session_id&order=id.desc&limit=1`);
  if (!s) return { fehler: true };
  if (s[0] && s[0].session_id) return { ziel: { user_id: wer, chat_id: s[0].session_id } };
  if (/^web:/.test(wer)) return { ziel: { user_id: wer, chat_id: wer } };
  return { unzustellbar: true };
}

const olItems = [];
if (olEnabled) {
  const hoursSinceOL = olLastRun ? (now.getTime() - olLastRun.getTime()) / (1000 * 60 * 60) : 999;
  if (hoursSinceOL >= olMinInterval && imZeitfenster(now)) {
    const ageCutoff = new Date(now.getTime() - olMinAgeDays * 24 * 60 * 60 * 1000).toISOString();
    const erneutAb = new Date(now.getTime() - UNZUSTELLBAR_TAGE * 24 * 60 * 60 * 1000).toISOString();
    const openLoops = await holen(`/rest/v1/memory_long?category=eq.open_loop&created_at=lt.${ageCutoff}&owner_user_id=not.is.null&metadata-%3E%3Enachgefragt_am=is.null&and=(or(expires_at.is.null,expires_at.gt.${nowISO}),or(metadata-%3E%3Eclosed.is.null,metadata-%3E%3Eclosed.neq.true),or(metadata-%3E%3Enachfrage_unzustellbar_am.is.null,metadata-%3E%3Enachfrage_unzustellbar_am.lt.${erneutAb}))&select=id,content,importance,created_at,expires_at,metadata,owner_user_id&order=importance.desc,created_at.asc&limit=50`);

    // 1. Kennungen aufloesen (je Besitzer einmal), zweite Sicherung der Filter im Code.
    const zielJe = new Map();
    const jePerson = new Map();
    const unzustellbar = [];
    for (const ol of (openLoops || [])) {
      const m = ol.metadata || {};
      if (m.closed === true || m.closed === 'true' || m.nachgefragt_am) continue;
      const owner = String(ol.owner_user_id || '').trim();
      if (!owner) continue;
      if (!zielJe.has(owner)) {
        let z;
        try { z = await zielVon(owner); } catch (e) { z = { fehler: true }; }
        zielJe.set(owner, z);
      }
      const z = zielJe.get(owner);
      if (z.unzustellbar) { unzustellbar.push(ol); continue; }
      if (!z.ziel) continue;   // Abfrage nicht lesbar: diesmal nicht, ohne Vermerk
      const schluessel = z.ziel.user_id;
      if (!jePerson.has(schluessel)) jePerson.set(schluessel, { ziel: z.ziel, active: [] });
      const p = jePerson.get(schluessel);
      if (p.active.length < 3) p.active.push(ol);
    }

    // 2. Unzustellbare vermerken, damit sie das Fenster nicht dauerhaft fuellen.
    for (const ol of unzustellbar) {
      try { await vorhabenVermerken(ol, 'nachfrage_unzustellbar_am'); } catch (e) { /* naechster Lauf */ }
    }

    // 3. Je Person eine Nachricht.
    for (const { ziel, active } of jePerson.values()) {
      if (olItems.length >= MAX_PERSONEN) break;
      // Erst vermerken, dann absenden: lieber eine Nachfrage zu wenig als
      // taeglich dieselbe. Scheitert der Vermerk, unterbleibt die Nachfrage.
      try {
        for (const ol of active) await vorhabenVermerken(ol, 'nachgefragt_am');
      } catch (e) { continue; }

      const lines = active.map(ol => {
        const days = Math.max(1, Math.floor((now.getTime() - new Date(ol.created_at).getTime()) / (1000 * 60 * 60 * 24)));
        return `- (id ${ol.id}, vor ${days} Tagen) ${ol.content}`;
      }).join('\n');

      const instruction = `Du fragst proaktiv beim User nach alten offenen Vorhaben. Sende EINE kurze, freundliche Nachricht (1-3 Sätze), die EINEN oder mehrere der folgenden offenen Punkte aufgreift. Sei nicht nervig: wenn ein Punkt zu trivial wirkt, lass ihn aus. Wenn alle Punkte trivial wirken, antworte nur mit dem Text [SKIP] und nichts anderem.\n\nWenn der User in seiner Antwort bestätigt, dass etwas erledigt/verworfen wurde, nutze memory_update auf die jeweilige id und setze metadata.closed=true (siehe Memory-Behavior-Regeln zu open_loop).\n\nOffene Vorhaben:\n${lines}`;

      olItems.push({
        json: {
          type: 'proactive_reminder',
          heartbeat_check_name: 'open_loop_check',
          actionId: null,
          message: instruction,
          chat_id: ziel.chat_id,
          user_id: ziel.user_id,
          source: 'scheduled_action',
          notify_mode: 'always'
        }
      });
    }
  }
}
items.unshift(...olItems);

if (items.length === 0) {
  return [{ json: { type: 'no_action' } }];
}

return items;

// Merge checker result with original action data for routing + update
const checkerResult = $input.first().json;
const actionData = $('Route by Notify Mode').first().json;

return [{
  json: {
    ...actionData,
    notify: checkerResult.notify || false,
    checkerMessage: checkerResult.message || ''
  }
}];

// Update scheduled action: last_run, run_count, next_run
const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const http = this.helpers.httpRequest;

// Get the action data — always original data from Should Notify
// (Send Telegram is a dead-end, doesn't feed into Update Action)
const item = $input.first().json;
const now = new Date();

// Proactive reminder: update heartbeat_config (configurable check_name to support multiple proactive triggers)
if (item.type === 'proactive_reminder') {
  const checkName = item.heartbeat_check_name || 'heartbeat';
  await http({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/heartbeat_config?check_name=eq.${checkName}`,
    headers: {
      'apikey': SUPABASE_KEY,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: { last_run: now.toISOString() }
  });
  return [{ json: { status: 'updated', type: 'proactive_reminder', check: checkName } }];
}

// Scheduled action: compute next_run and update
const actionId = item.actionId;
const schedule = item.schedule;
const tz = item.timezone || 'Europe/Berlin';
const runCount = (item.run_count || 0) + 1;
const maxRuns = item.max_runs;

function computeNextRun(schedule, tz) {
  const now = new Date();

  if (schedule.type === 'interval') {
    // Subtract 30s buffer so the next heartbeat cycle reliably finds this action due
    return new Date(now.getTime() + (schedule.minutes || 60) * 60000 - 30000).toISOString();
  }

  if (schedule.type === 'daily') {
    const [h, m] = (schedule.time || '08:00').split(':').map(Number);
    const userNow = new Date(now.toLocaleString('en-US', { timeZone: tz }));
    const target = new Date(userNow);
    target.setHours(h, m, 0, 0);
    if (target <= userNow) {
      target.setDate(target.getDate() + 1);
    }
    const diffMs = target.getTime() - userNow.getTime();
    return new Date(now.getTime() + diffMs).toISOString();
  }

  if (schedule.type === 'weekly') {
    const [h, m] = (schedule.time || '09:00').split(':').map(Number);
    const days = schedule.days || [1];
    const userNow = new Date(now.toLocaleString('en-US', { timeZone: tz }));
    const jsDay = userNow.getDay();
    const currentDay = jsDay === 0 ? 7 : jsDay;
    const currentMinutes = userNow.getHours() * 60 + userNow.getMinutes();
    const targetMinutes = h * 60 + m;

    let minDaysAhead = 8;
    for (const d of days) {
      let ahead = d - currentDay;
      if (ahead < 0) ahead += 7;
      if (ahead === 0 && currentMinutes >= targetMinutes) ahead = 7;
      if (ahead < minDaysAhead) minDaysAhead = ahead;
    }

    const target = new Date(userNow);
    target.setDate(target.getDate() + minDaysAhead);
    target.setHours(h, m, 0, 0);
    const diffMs = target.getTime() - userNow.getTime();
    return new Date(now.getTime() + diffMs).toISOString();
  }

  return new Date(now.getTime() + 3600000).toISOString();
}

const nextRun = computeNextRun(schedule, tz);
const shouldDisable = maxRuns !== null && maxRuns !== undefined && runCount >= maxRuns;

await http({
  method: 'PATCH',
  url: `${SUPABASE_URL}/rest/v1/scheduled_actions?id=eq.${actionId}`,
  headers: {
    'apikey': SUPABASE_KEY,
    'Content-Type': 'application/json',
    'Prefer': 'return=minimal'
  },
  body: {
    last_run: now.toISOString(),
    run_count: runCount,
    next_run: shouldDisable ? null : nextRun,
    enabled: !shouldDisable,
    updated_at: now.toISOString()
  }
});

return [{ json: { status: 'updated', actionId, runCount, nextRun: shouldDisable ? null : nextRun, disabled: shouldDisable } }];

const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const BRIDGE_URL = 'http://file-bridge:3200';

// 1. Cleanup expired files on File Bridge
let bridgeResult = { cleaned: 0 };
try {
  bridgeResult = await helpers.httpRequest({
    method: 'DELETE',
    url: BRIDGE_URL + '/cleanup'
  });
} catch(e) {
  // File Bridge may not be running yet
}

// 2. Cleanup expired metadata in DB
let dbResult = null;
try {
  dbResult = await helpers.httpRequest({
    method: 'DELETE',
    url: SUPABASE_URL + '/rest/v1/file_refs?expires_at=lt.' + new Date().toISOString(),
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': 'Bearer ' + SUPABASE_KEY
    }
  });
} catch(e) {}

return [{ json: { bridge_cleaned: bridgeResult.cleaned || 0, db_cleanup: 'done' } }];
